  {
    tool: 'pan',
    label: 'Hand Tool',
    accessibleLabel: 'Pan canvas',
    icon: 'pan',
    needsDocument: false,
    family: 'hand',
    slot: 19,
    shortcut: 'H',
  },
];
export const TOOL_FAMILIES = [...new Set(TOOL_REGISTRY.map((tool) => tool.family))]
  .map((family) => ({
    family,
    slot: Math.min(
      ...TOOL_REGISTRY.filter((tool) => tool.family === family).map((tool) => tool.slot),
    ),
    tools: TOOL_REGISTRY.filter((tool) => tool.family === family),
  }))
  .sort((a, b) => a.slot - b.slot);
export function toolDefinition(tool: Tool): ToolDefinition {
  const definition = TOOL_REGISTRY.find((item) => item.tool === tool) ?? TOOL_REGISTRY[0];
  if (!definition) throw new Error('Tool registry must contain at least one tool.');
  return definition;
}

export function toolForShortcut(key: string, current: Tool, shift: boolean): Tool | null {
  const normalized = key.toUpperCase();
  const matches = TOOL_REGISTRY.filter((item) => item.shortcut === normalized);
  if (matches.length === 0) return null;
  if (!shift || matches.length === 1) return matches[0]?.tool ?? null;
  const index = matches.findIndex((item) => item.tool === current);
  return matches[(index + 1 + matches.length) % matches.length]?.tool ?? null;
}

import type { Adjustment, SmartFilter } from '@freetoshop/core-document';
import type { FilterDraft, FilterKind } from './filterOperations.js';

export type ImageAdjustmentKind =
  | 'contrast'
  | 'levels'
  | 'hue-saturation'
  | 'grayscale'
  | 'invert'
  | 'threshold'
  | 'posterize';
export type ParameterizedImageAdjustmentKind =
  | 'contrast'
  | 'levels'
  | 'hue-saturation'
  | 'threshold'
  | 'posterize';
export type ImmediateImageAdjustmentKind = 'grayscale' | 'invert';
export type FilterMenuKind = 'gaussian-blur';
export type SmartFilterMenuKind = 'gaussian-blur';

export interface ImageAdjustmentDefinition {
  readonly id: string;
  readonly kind: ImageAdjustmentKind;
  readonly label: string;
  readonly order: number;
  readonly parameterized: boolean;
  readonly shortcut?: string;
  readonly separatorBefore?: boolean;
}
export interface FilterMenuDefinition {
  readonly id: string;
  readonly kind: FilterMenuKind;
  readonly label: string;
  readonly submenu: 'filter.blur';
  readonly order: number;
}
export interface AdjustmentLayerDefinition {
  readonly id: string;
  readonly type: Adjustment['type'];
  readonly label: string;
  readonly order: number;
}

export const IMAGE_ADJUSTMENT_DEFINITIONS = [
  {
    id: 'image.adjustments.contrast',
