  },
  {
    id: 'image.adjustments.grayscale',
    kind: 'grayscale',
    label: 'Grayscale',
    order: 40,
    parameterized: false,
    separatorBefore: true,
  },
  {
    id: 'image.adjustments.invert',
    kind: 'invert',
    label: 'Invert',
    order: 50,
