      aria-pressed={!menuItem ? tool === item.tool : undefined}
      onClick={activate}
      onContextMenu={(event) => {
        if (onOpenFamily) {
          event.preventDefault();
          onOpenFamily();
        }
      }}
    >
      <Icon name={item.icon} />
      <span className="tool-label">{item.label.replace(' Tool', '')}</span>
    </button>
