  let workBounds: Bounds | null;
  let selectionBuffer: Uint8ClampedArray | null = null;
  let selectionRegion: Bounds | null = null;

  if (selection == null) {
    // Full-layer adjust: entire layer is the working set by definition.
    workBounds = {
      left: 0,
      top: 0,
      right: layer.width - 1,
